/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );


// VARIABLES //

var debug = logger( 'plot:view:browser:routes:ack' );


// MAIN //

/**
* Callback invoked upon receiving an HTTP request.
*
* @private
* @param {Object} request - request object
* @param {Object} response - response object
* @param {Callback} next - callback to invoke upon completion
* @returns {void}
*/
function handler( request, response, next ) {
	var events;
	var id;
	var N;
	var i;
	var j;

	id = request.body;
	debug( 'Received an ack for event identifier: %s.', id );

	// Search for the acknowledged last event id...
	events = this.events;
	N = events.length;
	for ( i = N-1; i >= 0; i-- ) {
		if ( events[ i ].id === id ) {
			break;
		}
	}
	// If we found the identifier in our events database, we can safely remove all events up and including that event from our database...
	if ( i >= 0 ) {
		debug( 'Performing event database compaction...' );
		N -= i;
		for ( j = 0; j <= i; j++ ) {
			events[ j ] = events[ i ];
			i += 1;
		}
		events.length = N;
		debug( 'Successfully compacted event database.' );
	}
	next();
}


// EXPORTS //

module.exports = handler;
